(function(){var el=document.getElementById('mapa-entrega');if(!el)return;var started=false;
function init(){if(started)return;started=true;var l=document.createElement('link');l.rel='stylesheet';l.href='/assets/vendor/leaflet/leaflet.css';document.head.appendChild(l);var s=document.createElement('script');s.src='/assets/vendor/leaflet/leaflet.js';s.onload=draw;document.head.appendChild(s)}
function draw(){var L=window.L,loja=[-22.8897306,-47.1223038];var m=L.map(el,{scrollWheelZoom:false,dragging:!matchMedia('(pointer: coarse)').matches,touchZoom:true,doubleClickZoom:true,tap:false,zoomControl:true,minZoom:7,maxZoom:19});m.setView(loja,10);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(m);
L.circle(loja,{radius:15000,color:'#EA1D2C',weight:2,fillColor:'#EA1D2C',fillOpacity:.1}).addTo(m);
L.marker(loja,{icon:L.divIcon({className:'',html:'<div class="rg5-pin"></div>',iconSize:[12,12],iconAnchor:[6,6]}),keyboard:false}).addTo(m).bindPopup("<strong>Hick’s Burger</strong><br>Área de entrega: 15 km");
m.fitBounds(L.latLng(loja).toBounds(30000),{padding:[4,4]});var fs=document.createElement('button');fs.type='button';fs.className='rg5-fs';fs.setAttribute('aria-label','Ampliar mapa');fs.textContent='⤢';el.appendChild(fs);L.DomEvent.disableClickPropagation(fs);fs.addEventListener('click',function(){var on=el.classList.toggle('full');if(on){m.dragging.enable();m.scrollWheelZoom.enable()}else{m.scrollWheelZoom.disable();if(matchMedia('(pointer: coarse)').matches)m.dragging.disable()}fs.textContent=on?'✕':'⤢';fs.setAttribute('aria-label',on?'Fechar mapa':'Ampliar mapa');document.documentElement.style.overflow=on?'hidden':'';setTimeout(function(){m.invalidateSize();if(!on)m.fitBounds(L.latLng(loja).toBounds(30000),{padding:[4,4]})},60)})}
if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){io.disconnect();init()}},{rootMargin:'300px'});io.observe(el)}else init()})();